+
+    <div class="title-block">
+      <div class="kicker"><span class="pos">Position</span> &nbsp;&bull;&nbsp; ICML 2026 Main Track</div>
+      <h1>Quantum Deep Learning Still<br>Needs a Quantum Leap</h1>
+      <p class="authors">Hans Gundlach<sup>1</sup>&nbsp;&nbsp; Hrvoje Kukina<sup>2</sup>&nbsp;&nbsp; Jayson Lynch<sup>1</sup>&nbsp;&nbsp; Neil Thompson<sup>1</sup></p>
+      <p class="affil"><sup>1</sup>MIT FutureTech, CSAIL, Cambridge MA, USA &nbsp;&nbsp;|&nbsp;&nbsp; <sup>2</sup>TU Wien, Vienna, Austria</p>
+    </div>
+
+    <div class="right-cell">
+      <div class="icml-badge">
+        <div class="ic-conf">Forty-Third International Conference on Machine Learning</div>
+        <div><span class="ic-icml">ICML</span> <span class="ic-year">2026</span></div>
+        <div class="ic-where">Seoul, South Korea &middot; PMLR 306</div>
+      </div>
+      <div class="qr-cell">
+        <img src="figs/qr_arxiv.png" alt="arXiv QR">
+        <div class="qr-cap"><b>Read the paper</b><br>arXiv:2511.01253</div>
+      </div>
